CREATE PROCEDURE soft_check(IN p_amount DECIMAL(14,2))
  NO SQL
BEGIN
  IF p_amount > 10000 THEN
    SIGNAL SQLSTATE '01000' SET MESSAGE_TEXT = 'Large amount - review required';
  END IF;
  SELECT 'continued after the warning' AS outcome;
END
